@@ -39,6 +39,10 @@ public class KVMPhysicalDisk {
             rbdOpts += ":id=" + authUserName;
             rbdOpts += ":key=" + authSecret;
         }
+
+        rbdOpts += ":rbd_default_format=2";
+        rbdOpts += ":client_mount_timeout=30";
+
         return rbdOpts;
     }


